const question = $('Webhook').first().json.body.question || '';
let cls = { category: 'other', sensitive: true, search_query: question };
try {
  cls = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  cls = { category: 'other', sensitive: true, search_query: question };
}
const keywords = /(harass|suicid|self-harm|mental health|disciplin|appeal|abuse|assault)/i;
const sensitive = cls.sensitive === true || keywords.test(question);
return [{ json: { question, category: cls.category, search_query: cls.search_query || question, sensitive } }];

// SAMPLE knowledge base. Replace with a vector store or your real policy data.
const KB = [
  { policy: 'Fee Payment Policy', section: '3.1', effective: '2026-01-01', active: true,
    text: 'Tuition fees must be paid in full by the end of week 2 of each semester. Late payments attract a 5% penalty.' },
  { policy: 'Fee Payment Policy', section: '3.4', effective: '2026-01-01', active: true,
    text: 'Students may apply for a payment plan by submitting a request to the bursary before the fee deadline.' },
  { policy: 'Course Registration Policy', section: '2.2', effective: '2026-01-01', active: true,
    text: 'Course registration closes at the end of week 1. Late registration requires written approval from the head of department.' },
  { policy: 'Deferral Policy', section: '4.1', effective: '2026-01-01', active: true,
    text: 'A student may defer their studies for up to two semesters by submitting a deferral form to the registrar before week 4.' },
  { policy: 'Examination Regulations', section: '5.3', effective: '2026-01-01', active: true,
    text: 'A student who misses an examination with a valid medical reason may sit a supplementary examination in the next assessment period.' },
  { policy: 'Old Fee Policy', section: '3.1', effective: '2023-01-01', active: false,
    text: 'Tuition fees must be paid by the end of week 4 of each semester.' }
];
const stop = new Set(['the','and','for','can','how','what','when','who','are','you','with','from','that','this','have','does','need','about','your','their','into','will']);
const tokens = (s) => [...new Set(String(s).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !stop.has(w)))];
const { question, search_query } = $input.first().json;
const q = new Set(tokens(search_query));
const MIN_SCORE = 2;
const passages = KB.filter(p => p.active)
  .map(p => ({ ...p, score: tokens(p.policy + ' ' + p.text).filter(w => q.has(w)).length }))
  .filter(p => p.score >= MIN_SCORE)
  .sort((a, b) => b.score - a.score)
  .slice(0, 4);
const passagesText = passages.map((p, i) => `[${i + 1}] ${p.policy}, section ${p.section}: ${p.text}`).join('\n');
return [{ json: { question, found: passages.length > 0, passagesText, passages } }];

