const norm = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const ctx = $('Step 2 - Retrieve passages').first().json;
let out = { valid: false, reason: 'invalid JSON', result: null };
try {
  const r = JSON.parse($input.first().json.choices[0].message.content);
  const schemaOk = typeof r.answerable === 'boolean' && typeof r.answer === 'string' && typeof r.source === 'string' && typeof r.quote === 'string';
  if (!schemaOk) out.reason = 'schema check failed';
  else if (!r.answerable) out.reason = 'model said not answerable';
  else if (r.answer.split(/\s+/).length > 100) out.reason = 'answer over 100 words';
  else if (norm(r.quote).length < 15) out.reason = 'quote too short';
  else if (!norm(ctx.passagesText).includes(norm(r.quote))) out.reason = 'quote not found in retrieved passages';
  else out = { valid: true, reason: 'ok', result: r };
} catch (e) {
  out = { valid: false, reason: 'invalid JSON', result: null };
}
return [{ json: { ...out, question: ctx.question } }];

